// Recognises the products in a folder of existing code (brownfield): every
// folder, a few levels down, that one of the kits recognises as its kind of
// product. Nothing in the code is changed; what is found is proposed, and the
// owner confirms it.
import { readdirSync } from "node:fs";
import { basename, join } from "node:path";
const SKIPPED = new Set(["node_modules", ".git", "dist", "build", "coverage"]);
const DEPTH = 3;
// The products found under `folder`, each with a free id and port. A
// folder a kit recognises is not looked into further (a product's own
// subfolders are part of it). A fallback kit only takes a folder in which
// nothing was found below, so a project's own apps win over the project
// as a whole.
export function detectProducts(folder, kits) {
    const specific = kits.filter((k) => !k.fallback);
    const fallbacks = kits.filter((k) => k.fallback);
    const look = (path, depth) => {
        const own = candidateIn(path, specific);
        if (own)
            return [own];
        const below = depth < DEPTH
            ? folders(path).flatMap((entry) => look(join(path, entry), depth + 1))
            : [];
        if (below.length > 0)
            return below;
        const other = candidateIn(path, fallbacks);
        return other ? [other] : [];
    };
    return withFreePorts(withFreeIds(look(folder, 0)));
}
// The product the first kit that recognises `path` finds there.
function candidateIn(path, kits) {
    for (const kit of kits) {
        const detected = kit.detect(path);
        if (detected)
            return {
                ...detected,
                id: idFrom(basename(path)),
                kind: kit.kind,
                kit: kit.id,
                folder: path,
                ...((detected.port ?? kit.port)
                    ? { port: detected.port ?? kit.port }
                    : {}),
            };
    }
    return null;
}
function folders(path) {
    try {
        return readdirSync(path, { withFileTypes: true })
            .filter((entry) => entry.isDirectory() &&
            !SKIPPED.has(entry.name) &&
            !entry.name.startsWith("."))
            .map((entry) => entry.name)
            .sort((a, b) => a.localeCompare(b));
    }
    catch {
        return [];
    }
}
// "My Shop_App" → "my-shop-app"; "app" when nothing is left.
export function idFrom(name) {
    const words = name
        .toLowerCase()
        .split(/[^a-z0-9]+/)
        .filter(Boolean);
    let id = words.join("-");
    // An id starts with a letter.
    while (id !== "" && !/[a-z]/.test(id.charAt(0)))
        id = id.slice(1);
    return id || "app";
}
// Two products found in folders with the same name get "-2", "-3".
function withFreeIds(found) {
    const taken = new Set();
    return found.map((candidate) => {
        let id = candidate.id;
        let n = 1;
        while (taken.has(id)) {
            n += 1;
            id = `${candidate.id}-${String(n)}`;
        }
        taken.add(id);
        return { ...candidate, id };
    });
}
// Two products that would answer on the same port: the later one moves up.
export function withFreePorts(found) {
    const taken = new Set();
    return found.map((candidate) => {
        if (candidate.port === undefined)
            return candidate;
        let port = candidate.port;
        while (taken.has(port))
            port += 1;
        taken.add(port);
        return { ...candidate, port };
    });
}
